USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetPending @EmployeeId VARCHAR(30)
AS BEGIN
 SET NOCOUNT ON;
 SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,
        r.CONCERN_DIVISION_ID,ou.ORG_UNIT_NAME CONCERN_DIVISION_NAME,
        u.DISPLAY_NAME REQUESTED_BY_NAME,
        (SELECT COUNT(*) FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1) ITEM_COUNT
 FROM dbo.WORKFLOW_INSTANCE w
 JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID
 JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID
 JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND s.IS_ACTIVE=1
 JOIN dbo.ORG_UNIT ou ON ou.ORG_UNIT_ID=s.ORG_UNIT_ID
 JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID
 JOIN dbo.CONCERN_DIVISION_AUTHORITY a ON a.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID
      AND a.EMPLOYEE_ID=@EmployeeId AND a.IS_ACTIVE=1
      AND a.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())
      AND (a.EFFECTIVE_TO IS NULL OR a.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))
 WHERE w.CURRENT_STAGE='CONCERN_AUTHORITY'
   AND w.CURRENT_STATUS='PENDING'
   AND w.COMPLETED_DATE IS NULL
   AND h.CURRENT_STATUS='IN_WORKFLOW'
   AND h.IS_ACTIVE=1
   AND EXISTS
   (
       SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT x
       WHERE x.REQUISITION_ID=h.REQUISITION_ID
         AND x.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'
         AND x.IS_CURRENT=1
         AND x.ASSIGNED_TO_ORG_UNIT_ID=s.ORG_UNIT_ID
   )
 ORDER BY h.REQUESTED_DATE;
END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON;DECLARE @requester VARCHAR(30);SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_AUTHORITY a ON a.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND a.EMPLOYEE_ID=@EmployeeId AND a.IS_ACTIVE=1 WHERE h.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_AUTHORITY'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT x WHERE x.REQUISITION_ID=@RequisitionId AND x.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'AND x.IS_CURRENT=1);IF @requester IS NULL BEGIN SELECT TOP(0) REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetReviewContext @RequisitionId BIGINT,@EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON;SELECT r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,w.CURRENT_STAGE,r.DESTINATION_AFTER_CONCERN NEXT_DESTINATION,d.CONCERN_DIVISION_ID,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME,h.ACTION_BY_EMPLOYEE_ID CONCERN_OFFICIAL_EMPLOYEE_ID,u.DISPLAY_NAME CONCERN_OFFICIAL_NAME,h.REMARKS CONCERN_OFFICIAL_REMARKS,h.ACTION_DATETIME FORWARDED_DATE FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_SETUP d ON d.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=d.ORG_UNIT_ID JOIN dbo.CONCERN_DIVISION_AUTHORITY a ON a.CONCERN_DIVISION_ID=d.CONCERN_DIVISION_ID AND a.EMPLOYEE_ID=@EmployeeId AND a.IS_ACTIVE=1 CROSS APPLY(SELECT TOP 1 x.ACTION_BY_EMPLOYEE_ID,x.REMARKS,x.ACTION_DATETIME FROM dbo.WORKFLOW_HISTORY x WHERE x.REQUISITION_ID=@RequisitionId AND x.ACTION_TYPE='CONCERN_FORWARD_TO_AUTHORITY'ORDER BY x.ACTION_DATETIME DESC)h LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.ACTION_BY_EMPLOYEE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.CURRENT_STAGE='CONCERN_AUTHORITY'AND w.CURRENT_STATUS='PENDING'AND w.COMPLETED_DATE IS NULL;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetAll @EmployeeId VARCHAR(30),@RequisitionNo VARCHAR(30)=NULL,@AssetId BIGINT=NULL,@RequisitionType VARCHAR(20)=NULL,@Status VARCHAR(40)=NULL,@FromDate DATE=NULL,@ToDate DATE=NULL AS BEGIN SET NOCOUNT ON;SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.REQUESTED_BY_EMPLOYEE_ID,COALESCE(u.DISPLAY_NAME,h.REQUESTED_BY_EMPLOYEE_ID)REQUESTED_BY_NAME,org.ORG_UNIT_NAME,COALESCE((SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),x.ITEM_NAME_SNAPSHOT),', ')FROM(SELECT DISTINCT i.ITEM_NAME_SNAPSHOT FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)x),'')ASSETS,COALESCE((SELECT STRING_AGG(CONVERT(NVARCHAR(MAX),x.REQ_TYPE),', ')FROM(SELECT DISTINCT i.REQ_TYPE FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1)x),'')REQUISITION_TYPES,COALESCE((SELECT SUM(i.QUANTITY)FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1),0)TOTAL_QUANTITY,h.TOTAL_ESTIMATED_AMOUNT,h.CURRENT_STATUS,w.CURRENT_STAGE PENDING_STAGE,CASE WHEN assign.ASSIGNED_TO_EMPLOYEE_ID IS NOT NULL THEN COALESCE(au.DISPLAY_NAME,assign.ASSIGNED_TO_EMPLOYEE_ID)WHEN assign.ASSIGNMENT_TYPE='MANAGER'THEN CONCAT('Branch Manager Pool - ',org.ORG_UNIT_NAME)WHEN assign.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL'THEN'Procurement Officer Pool'WHEN assign.ASSIGNMENT_TYPE='CONCERN_OFFICIAL'THEN'Concern Official Pool'WHEN assign.ASSIGNMENT_TYPE='CONCERN_AUTHORITY'THEN'Concern Division Authority Pool'WHEN assign.ASSIGNMENT_TYPE='PROCUREMENT_AUTHORITY_POOL'THEN'Procurement Authority Pool'WHEN assign.ASSIGNMENT_TYPE='MAKER'THEN'Maker'ELSE NULL END PENDING_WITH FROM dbo.REQUISITION_HEADER h JOIN dbo.ORG_UNIT org ON org.ORG_UNIT_ID=h.REQUESTED_ORG_UNIT_ID LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=h.REQUESTED_BY_EMPLOYEE_ID LEFT JOIN dbo.WORKFLOW_INSTANCE w ON w.REQUISITION_ID=h.REQUISITION_ID AND w.COMPLETED_DATE IS NULL OUTER APPLY(SELECT TOP(1)x.ASSIGNMENT_TYPE,x.ASSIGNED_TO_EMPLOYEE_ID FROM dbo.REQUISITION_ASSIGNMENT x WHERE x.REQUISITION_ID=h.REQUISITION_ID AND x.IS_CURRENT=1 ORDER BY x.ASSIGNED_DATE DESC,x.ASSIGNMENT_ID DESC)assign LEFT JOIN dbo.APP_USER_CACHE au ON au.EMPLOYEE_ID=assign.ASSIGNED_TO_EMPLOYEE_ID WHERE h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM si JOIN dbo.WORKFLOW_RULE sr ON sr.ASSET_ID=si.ASSET_ID AND sr.REQ_TYPE=si.REQ_TYPE AND sr.IS_ACTIVE=1 JOIN dbo.CONCERN_DIVISION_AUTHORITY authorityMap ON authorityMap.CONCERN_DIVISION_ID=sr.CONCERN_DIVISION_ID AND authorityMap.EMPLOYEE_ID=@EmployeeId AND authorityMap.IS_ACTIVE=1 AND authorityMap.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(authorityMap.EFFECTIVE_TO IS NULL OR authorityMap.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))WHERE si.REQUISITION_ID=h.REQUISITION_ID AND si.IS_ACTIVE=1)AND(NULLIF(@RequisitionNo,'')IS NULL OR h.REQUISITION_NO LIKE'%'+@RequisitionNo+'%')AND(NULLIF(@Status,'')IS NULL OR h.CURRENT_STATUS=@Status)AND(@FromDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)>=@FromDate)AND(@ToDate IS NULL OR CONVERT(DATE,h.REQUESTED_DATE)<=@ToDate)AND(@AssetId IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.ASSET_ID=@AssetId AND i.IS_ACTIVE=1))AND(NULLIF(@RequisitionType,'')IS NULL OR EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=h.REQUISITION_ID AND i.REQ_TYPE=@RequisitionType AND i.IS_ACTIVE=1))ORDER BY h.REQUESTED_DATE DESC;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernAuthority_GetAllDetail @RequisitionId BIGINT,@EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON;DECLARE @requester VARCHAR(30);SELECT @requester=h.REQUESTED_BY_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h WHERE h.REQUISITION_ID=@RequisitionId AND h.IS_ACTIVE=1 AND EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM si JOIN dbo.WORKFLOW_RULE sr ON sr.ASSET_ID=si.ASSET_ID AND sr.REQ_TYPE=si.REQ_TYPE AND sr.IS_ACTIVE=1 JOIN dbo.CONCERN_DIVISION_AUTHORITY authorityMap ON authorityMap.CONCERN_DIVISION_ID=sr.CONCERN_DIVISION_ID AND authorityMap.EMPLOYEE_ID=@EmployeeId AND authorityMap.IS_ACTIVE=1 AND authorityMap.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(authorityMap.EFFECTIVE_TO IS NULL OR authorityMap.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))WHERE si.REQUISITION_ID=h.REQUISITION_ID AND si.IS_ACTIVE=1);IF @requester IS NULL BEGIN SELECT TOP(0)REQUISITION_ID,REQUISITION_NO,REQUESTED_BY_EMPLOYEE_ID,REQUESTED_ORG_UNIT_ID,CAST(''AS NVARCHAR(200))ORG_UNIT_NAME,REQUESTED_DATE,JUSTIFICATION,TOTAL_ESTIMATED_AMOUNT,CURRENT_STATUS FROM dbo.REQUISITION_HEADER;RETURN;END;EXEC dbo.usp_Requisition_GetMakerDetail @RequisitionId,@requester;END;
GO
